'use strict';
const $=s=>document.querySelector(s),M=CustomerAllocations,customerId=new URLSearchParams(location.search).get('id'),owner=KashierData.userId(),key='kashier.customer-allocation.pending.v1.'+owner+'.'+customerId;
const active=()=>Boolean(owner)&&KashierData.loggedIn()&&KashierData.userId()===owner,format=v=>new Intl.NumberFormat('en-US').format(BigInt(v)),date=v=>new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(v));
let snapshot=null,pending=null,busy=false,blocked=false,request=0,selectedReversal=null;
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function status(text){$('#allocation-status').textContent=text;}
function controls(){const locked=blocked||busy||Boolean(pending)||!snapshot||!active();for(const id of ['payment','charge','amount','note','submit'])$('#allocation-'+id).disabled=locked;$('#allocation-retry').hidden=!pending;$('#allocation-retry').disabled=busy||!active();$('#allocation-refresh').disabled=busy;$('#allocation-reverse-close').disabled=busy;$('#allocation-reverse-submit').disabled=locked;$('#allocation-reason').disabled=locked;for(const e of document.querySelectorAll('[data-allocation-reverse]'))e.disabled=locked;}
function invalidate(){request++;snapshot=null;$('#allocation-content').hidden=true;$('#allocation-entries').replaceChildren();$('#allocation-history').replaceChildren();$('#allocation-name').textContent='—';if($('#allocation-reverse-dialog').open)$('#allocation-reverse-dialog').close();controls();}
function limit(){if(!snapshot)return;const p=snapshot.entries.get($('#allocation-payment').value),c=snapshot.entries.get($('#allocation-charge').value);$('#allocation-limit').textContent=p&&c?'زۆرترین بڕی ڕێگەپێدراو: '+format(M.money(p.available)<M.money(c.available)?p.available:c.available)+' دینار.':'پارەدان و قەرزێک هەڵبژێرە.';}
function populate(id,kind){const select=$('#allocation-'+id);select.replaceChildren();const placeholder=node('option',kind==='repayment'?'پارەدان هەڵبژێرە':'قەرز هەڵبژێرە');placeholder.value='';select.append(placeholder);for(const e of snapshot.data.entries.filter(e=>e.kind===kind&&M.money(e.available)>0n)){const opt=node('option','D-'+e.movement_no+' · '+format(e.available)+' دینار · '+e.note);opt.value=e.id;select.append(opt);}select.value='';}
function render(){const data=snapshot.data;$('#allocation-name').textContent=data.customer.name;$('#allocation-balance').textContent=format(snapshot.balance);$('#allocation-unassigned').textContent=format(snapshot.unallocated);$('#allocation-capacity').textContent=format(snapshot.capacity);$('#allocation-warning').textContent=snapshot.unallocated>0n?'هێشتا پارەدانی دابەشنەکراو هەیە. «نەبەستراو» لە هەر قەرزێکدا قەرزی کۆتایی ئەو پسوولەیە نییە؛ سەرەتا پارەدانەکان بە ڕاستی دابەش بکە.':'پارەدانەکان هەموویان دیاریکراون؛ بڕی نەبەستراوی هەر قەرزێک ماوەی ئەو قەرزەیە.';populate('payment','repayment');populate('charge','charge');limit();$('#allocation-entries').replaceChildren();for(const e of data.entries){const row=node('tr'),source=node('td',e.kind==='repayment'?'پارەی وەرگیراو':e.sale_id?'قەرزی فرۆشتن':'قەرزی دەستی');if(e.sale_id){const link=node('a','پسوولە');link.href='receipt.html?id='+e.sale_id;source.append(node('br'),link);}row.append(node('td','D-'+e.movement_no),source,...[e.amount,e.reversed,e.allocated,e.available].map(v=>node('td',format(v))));$('#allocation-entries').append(row);}$('#allocation-history').replaceChildren();for(const a of data.allocations){const row=node('tr'),action=node('td');if(!a.reversal_id){const b=node('button','هەڵوەشاندنەوەی بەستنەوە');b.className='secondary';b.setAttribute('data-allocation-reverse','');b.addEventListener('click',()=>{if(busy||pending||!active())return;selectedReversal=a.id;$('#allocation-reason').value='';$('#allocation-reverse-summary').textContent=reference(a)+' · '+format(a.amount)+' دینار';$('#allocation-reverse-dialog').showModal();});action.append(b);}row.append(node('td',date(a.created_at)),node('td',reference(a)),node('td',format(a.amount)),node('td',a.note),node('td',a.reversal_id?'هەڵوەشاوە: '+a.reversal_reason+' · '+date(a.reversed_at):'چالاک'),action);$('#allocation-history').append(row);}$('#allocation-empty').hidden=data.allocations.length!==0;$('#allocation-content').hidden=false;controls();}
function reference(a){return 'D-'+snapshot.entries.get(a.payment_entry_id).movement_no+' ← D-'+snapshot.entries.get(a.charge_entry_id).movement_no;}
async function load(){invalidate();const mine=++request;if(!active()){status('دووبارە بچۆ ژوورەوە.');location.replace('auth.html?next='+encodeURIComponent('customer-allocations.html?id='+customerId));return;}if(!M.uuid(customerId)){status('ناسنامەی کڕیار نادروستە.');return;}status('خوێندنەوەی پارەدان و قەرزەکان…');try{const data=await KashierData.getCustomerAllocations(customerId);if(mine!==request)return;if(!active())throw Error('هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.');snapshot=M.validate(data,customerId,owner);render();status(blocked?'داواکاری پارێزراو نەخوێندرایەوە؛ پێش کردارێکی نوێ تۆمارەکان بپشکنە.':pending?'داواکارییەکی ماوە هەیە؛ هەمان داواکاری بپشکنەوە.':'حسابەکە خوێندرایەوە؛ بۆ زانیاری نوێ نوێکردنەوە دابگرە.');}catch(error){if(mine===request){invalidate();status((globalThis.KashierLocale?.message(error.message)??error.message));}}finally{controls();}}
function persist(value){try{sessionStorage.setItem(key,JSON.stringify(value));return true;}catch{status('داواکاری نەپارێزرا؛ هیچ مامەڵەیەک نەنێردرا.');return false;}}
function validPending(p){if(!p||p.version!==1||p.owner!==owner||!['allocate','reverse'].includes(p.kind)||!M.uuid(p.payload?.p_id)||p.payload.p_customer!==customerId)return false;const x=p.payload;if(p.kind==='reverse')return M.uuid(x.p_allocation)&&typeof x.p_reason==='string'&&x.p_reason.trim().length>0&&x.p_reason.length<=500;try{return M.uuid(x.p_payment)&&M.uuid(x.p_charge)&&x.p_payment!==x.p_charge&&M.money(x.p_amount,100000000000000n)>0n&&typeof x.p_note==='string'&&x.p_note.trim().length>0&&x.p_note.length<=500;}catch{return false;}}
async function send(){if(busy||!pending)return;if(!active()){invalidate();status('هەژمارەکە گۆڕاوە؛ هیچ داواکارییەک نەنێردرا.');return;}const mine=request,item=pending;busy=true;controls();status('تۆمارکردن…');try{const result=await (item.kind==='allocate'?KashierData.allocateCustomerPayment(item.payload):KashierData.reverseCustomerAllocation(item.payload));if(mine!==request||!active())return;if(result?.id!==item.payload.p_id||result.customer_id!==customerId||item.kind==='allocate'&&result.amount!==item.payload.p_amount)throw Error('وەڵامی داواکاری پشتڕاست نەکرایەوە.');pending=null;try{sessionStorage.removeItem(key);}catch{}if($('#allocation-reverse-dialog').open)$('#allocation-reverse-dialog').close();$('#allocation-amount').value='';$('#allocation-note').value='';busy=false;await load();if(snapshot)status('داواکاری تۆمار کرا. کۆی قەرز و سندوق نەگۆڕا.');}catch(error){if(mine!==request||!active())return;const rejected=['allocation_invalid_request','allocation_invalid_amount','allocation_note_required','allocation_entry_unavailable','allocation_payment_exceeded','allocation_charge_exceeded','allocation_already_reversed'];if(rejected.includes(error.saleCode)){pending=null;try{sessionStorage.removeItem(key);}catch{}busy=false;if($('#allocation-reverse-dialog').open)$('#allocation-reverse-dialog').close();await load();status((globalThis.KashierLocale?.message(error.message)??error.message));}else{status('دۆخی داواکاری پشتڕاست نییە؛ بۆ ڕێگریکردن لە دووبارەبوونەوە تەنها هەمان داواکاری بپشکنەوە.');}}finally{busy=false;controls();}}
$('#allocation-form').addEventListener('submit',event=>{event.preventDefault();if(blocked||busy||pending||!snapshot||!active()||!$('#allocation-form').reportValidity())return;try{const payment=$('#allocation-payment').value,charge=$('#allocation-charge').value,amount=M.inputAmount($('#allocation-amount').value),note=$('#allocation-note').value.trim(),p=snapshot.entries.get(payment),c=snapshot.entries.get(charge),n=M.money(amount,100000000000000n);if(!p||!c||n<1n||n>M.money(p.available)||n>M.money(c.available))throw Error('بڕ لە پارەی دابەشنەکراو یان قەرزی نەبەستراو زیاترە.');if(!note)throw Error('هۆکار بنووسە.');const item={version:1,owner,kind:'allocate',payload:{p_id:crypto.randomUUID(),p_customer:customerId,p_payment:payment,p_charge:charge,p_amount:amount,p_note:note}};if(!persist(item))return;pending=item;send();}catch(error){status((globalThis.KashierLocale?.message(error.message)??error.message));}});
$('#allocation-reverse-form').addEventListener('submit',event=>{event.preventDefault();if(blocked||busy||pending||!snapshot||!active()||!selectedReversal||!$('#allocation-reverse-form').reportValidity())return;const reason=$('#allocation-reason').value.trim();if(!reason){status('هۆکاری هەڵوەشاندنەوە بنووسە.');return;}const item={version:1,owner,kind:'reverse',payload:{p_id:crypto.randomUUID(),p_customer:customerId,p_allocation:selectedReversal,p_reason:reason}};if(!persist(item))return;pending=item;send();});
$('#allocation-payment').addEventListener('change',limit);$('#allocation-charge').addEventListener('change',limit);$('#allocation-refresh').addEventListener('click',()=>{load();});$('#allocation-retry').addEventListener('click',send);$('#allocation-reverse-close').addEventListener('click',()=>{if(!busy)$('#allocation-reverse-dialog').close();});$('#allocation-reverse-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
if(M.uuid(customerId))$('#allocation-back').href='customer.html?id='+customerId;
try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved){if(!validPending(saved))throw Error();pending=saved;}}catch{blocked=true;status('داواکاری پارێزراو نەخوێندرایەوە؛ پێش کردارێکی نوێ تۆمارەکان بپشکنە.');controls();}
window.addEventListener('pagehide',invalidate);window.addEventListener('pageshow',e=>{if(e.persisted){invalidate();location.reload();}});
load();
